"""
scripts/i18n/translate_all_eu_languages.py
Parallel high-speed translation for EU languages and existing locales.
Supports all 24 official EU languages.
"""

import concurrent.futures
import json
import os
import re
import sys
import time
import urllib.parse
import urllib.request

EN_PATH = "web/apps/portal/src/locales/en/messages.json"
LOCALES_DIR = "web/apps/portal/src/locales"

NEW_KEYS = {
    "exams.ai_draft_badge": "AI Draft",
    "exams.ai_draft_tooltip": "Generated by an AI assistant — awaiting your review",
    "exams.ai_create_title": "AI Exam Creator API",
    "exams.ai_create_desc": "External AI agents can draft complete exams using your teacher credentials. You can inspect and polish them below.",
}

# All 10 remaining EU languages
NEW_EU_LANGUAGES = {
    "bg": {"code": "bg", "name": "Bulgarian (Български)"},
    "hr": {"code": "hr", "name": "Croatian (Hrvatski)"},
    "et": {"code": "et", "name": "Estonian (Eesti)"},
    "ga": {"code": "ga", "name": "Irish (Gaeilge)"},
    "lv": {"code": "lv", "name": "Latvian (Latviešu)"},
    "lt": {"code": "lt", "name": "Lithuanian (Lietuvių)"},
    "mt": {"code": "mt", "name": "Maltese (Malti)"},
    "ro": {"code": "ro", "name": "Romanian (Română)"},
    "sk": {"code": "sk", "name": "Slovak (Slovenčina)"},
    "sl": {"code": "sl", "name": "Slovenian (Slovenščina)"},
}

EXISTING_LANG_CODES = {
    "ar": "ar", "cn": "zh-CN", "cs": "cs", "da": "da", "de": "de", "el": "el",
    "es": "es", "fi": "fi", "fr": "fr", "he": "iw", "hu": "hu", "id": "id",
    "it": "it", "ja": "ja", "ko": "ko", "nl": "nl", "no": "no", "pl": "pl",
    "pt": "pt", "pt-BR": "pt", "ru": "ru", "sv": "sv", "th": "th", "tr": "tr",
    "uk": "uk", "vi": "vi",
}

KNOWN_UNIVERSAL = {
    "PDF", "LaTeX", "STT", "OCR", "SEB", "JSON", "ZIP", "CSV",
    "Planned Education", "PlannedEducation", "Email", "URL", "IP",
    "PIN", "2FA", "ID", "WebAuthn"
}


def translate_chunk_api(chunk: list[str], target_lang: str) -> dict[str, str]:
    """Translate a chunk of strings in a single HTTP request."""
    res = {}
    combined = " ||| ".join(chunk)
    url = f"https://clients5.google.com/translate_a/t?client=dict-chrome-ex&sl=en&tl={target_lang}&q={urllib.parse.quote(combined)}"
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"})
    try:
        with urllib.request.urlopen(req, timeout=12) as r:
            data = json.loads(r.read().decode("utf-8"))
            raw = data[0] if isinstance(data[0], str) else data[0][0]
            parts = [p.strip() for p in re.split(r"\s*\|{2,3}\s*|\s*｜{2,3}｜*\s*", raw)]
            if len(parts) == len(chunk):
                for orig, trans in zip(chunk, parts):
                    res[orig] = trans
                return res
    except Exception:
        pass

    # Fallback to single string per item if delimiter split was mismatched
    for s in chunk:
        s_clean = s.strip()
        if s_clean in KNOWN_UNIVERSAL or len(s_clean) == 0:
            res[s] = s
            continue
        try:
            s_url = f"https://clients5.google.com/translate_a/t?client=dict-chrome-ex&sl=en&tl={target_lang}&q={urllib.parse.quote(s)}"
            s_req = urllib.request.Request(s_url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(s_req, timeout=6) as r:
                d = json.loads(r.read().decode("utf-8"))
                val = d[0] if isinstance(d[0], str) else d[0][0]
                res[s] = val.strip()
        except Exception:
            res[s] = s
        time.sleep(0.01)

    return res


def update_existing_locales():
    """Add the 4 missing keys to all 25 existing non-English locales."""
    print("=== Step 1: Checking and updating existing locales ===", flush=True)
    with open(EN_PATH, "r", encoding="utf-8") as f:
        en_data = json.load(f)

    for loc, tl in sorted(EXISTING_LANG_CODES.items()):
        loc_dir = os.path.join(LOCALES_DIR, loc)
        loc_file = os.path.join(loc_dir, "messages.json")
        if not os.path.exists(loc_file):
            continue

        with open(loc_file, "r", encoding="utf-8") as f:
            loc_data = json.load(f)

        missing_keys = [k for k in NEW_KEYS if k not in loc_data]
        if missing_keys:
            trans_map = translate_chunk_api([NEW_KEYS[k] for k in missing_keys], tl)
            for k in missing_keys:
                loc_data[k] = trans_map.get(NEW_KEYS[k], NEW_KEYS[k])

            with open(loc_file, "w", encoding="utf-8") as f:
                json.dump(loc_data, f, ensure_ascii=False, indent=2)
            print(f"[{loc}] Added {len(missing_keys)} keys (Total: {len(loc_data)})", flush=True)
        else:
            print(f"[{loc}] Up to date ({len(loc_data)} keys).", flush=True)


def translate_single_language(loc: str, info: dict, en_data: dict):
    """Translate one complete language pack with live progress updates."""
    loc_dir = os.path.join(LOCALES_DIR, loc)
    os.makedirs(loc_dir, exist_ok=True)
    loc_file = os.path.join(loc_dir, "messages.json")

    existing_data = {}
    if os.path.exists(loc_file):
        try:
            with open(loc_file, "r", encoding="utf-8") as f:
                existing_data = json.load(f)
        except Exception:
            existing_data = {}

    keys = list(en_data.keys())
    missing_keys = [k for k in keys if k not in existing_data]
    if not missing_keys:
        print(f"[{loc}] {info['name']}: 100% complete ({len(existing_data)} keys).", flush=True)
        return

    print(f"[{loc}] Starting {info['name']}: {len(missing_keys)} keys remaining...", flush=True)

    batch_chunk_size = 30
    for b_start in range(0, len(missing_keys), batch_chunk_size):
        chunk_keys = missing_keys[b_start:b_start + batch_chunk_size]
        chunk_vals = [en_data[k] for k in chunk_keys]

        t_map = translate_chunk_api(chunk_vals, loc)
        for k, val in zip(chunk_keys, chunk_vals):
            existing_data[k] = t_map.get(val, val)

        done_count = len(existing_data)
        pct = int((done_count / len(keys)) * 100)
        print(f"  [{loc}] {done_count}/{len(keys)} keys ({pct}%)", flush=True)

        with open(loc_file, "w", encoding="utf-8") as f:
            json.dump(existing_data, f, ensure_ascii=False, indent=2)

        time.sleep(0.02)

    print(f"[{loc}] COMPLETED {info['name']} ({len(existing_data)}/{len(keys)} keys).", flush=True)


def generate_new_eu_locales_parallel():
    """Run translation across the 10 EU languages with 5 parallel threads."""
    print("\n=== Step 2: Parallel translation of 10 new EU languages ===", flush=True)
    with open(EN_PATH, "r", encoding="utf-8") as f:
        en_data = json.load(f)

    with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
        futures = {
            executor.submit(translate_single_language, loc, info, en_data): loc
            for loc, info in NEW_EU_LANGUAGES.items()
        }
        for future in concurrent.futures.as_completed(futures):
            loc = futures[future]
            try:
                future.result()
            except Exception as e:
                print(f"[{loc}] Error during translation: {e}", file=sys.stderr)


def main():
    start_time = time.time()
    update_existing_locales()
    generate_new_eu_locales_parallel()
    elapsed = time.time() - start_time
    print(f"\nAll EU and global locales completed successfully in {elapsed:.1f}s!", flush=True)


if __name__ == "__main__":
    main()
